import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long f = Long.parseLong(next());
        long s = Long.parseLong(next());

        final long MOD = 1000000007L;
        int target = (int) s;
        long[] ways = new long[target + 1];
        long[] next = new long[target + 1];
        ways[0] = 1;
        for (int i = 0; i < n; i++) {
            Arrays.fill(next, 0);
            for (int t = 0; t <= target; t++) {
                if (ways[t] == 0) continue;
                for (int face = 1; face <= f && t + face <= target; face++) {
                    next[t + face] = (next[t + face] + ways[t]) % MOD;
                }
            }
            long[] swap = ways;
            ways = next;
            next = swap;
        }
        System.out.println(ways[target]);
    }
}
